-- Etapa1: esquema nativo vacio; sin permisos, importaciones, notificaciones o escrituras externas.
CREATE TABLE IF NOT EXISTS crm_note (
  id_note BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna propia de la nota',
  public_id_note CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico estable; no identifica una copia externa',
  author_user_id_note BIGINT UNSIGNED NOT NULL COMMENT 'Autor inmutable relacionado con sec_user, nunca un ID ERP',
  title_note VARCHAR(200) NULL COMMENT 'Titulo opcional de la nota',
  content_note JSON NOT NULL COMMENT 'Contenido estructurado validado por API; no HTML arbitrario',
  plain_text_note TEXT NOT NULL COMMENT 'Texto derivado para lectura y busqueda con control de acceso',
  color_note CHAR(7) NOT NULL DEFAULT '#FFFF88' COMMENT 'Color RGB validado por API, sin significado de permiso',
  priority_note VARCHAR(16) NOT NULL DEFAULT 'normal' COMMENT 'Prioridad low, normal o high independiente del estado',
  visibility_note VARCHAR(16) NOT NULL DEFAULT 'private' COMMENT 'Private para autor o shared para participantes explicitamente autorizados',
  status_note VARCHAR(16) NOT NULL DEFAULT 'open' COMMENT 'Estado open, completed o archived; no es lectura individual',
  version_note INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Version optimista del contenido y acciones de negocio',
  updated_by_user_id_note BIGINT UNSIGNED NOT NULL COMMENT 'Autor responsable de la ultima modificacion de la nota original',
  completed_at_note DATETIME(3) NULL COMMENT 'Fecha UTC en que el autor completo la nota',
  completed_by_user_id_note BIGINT UNSIGNED NULL COMMENT 'Autor que completo la nota; no un destinatario',
  archived_at_note DATETIME(3) NULL COMMENT 'Fecha UTC del archivo logico; no destruye respuestas ni historial',
  archived_by_user_id_note BIGINT UNSIGNED NULL COMMENT 'Autor que archivo la nota',
  created_at_note DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion UTC de la nota principal nativa',
  updated_at_note DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultimo cambio UTC de contenido; el layout se guarda separado',
  PRIMARY KEY (id_note),
  UNIQUE KEY uq_note_public (public_id_note),
  KEY ix_note_author_status (author_user_id_note,status_note,updated_at_note,id_note),
  CONSTRAINT fk_note_author FOREIGN KEY (author_user_id_note) REFERENCES sec_user(id_user),
  CONSTRAINT fk_note_updated_by FOREIGN KEY (updated_by_user_id_note) REFERENCES sec_user(id_user),
  CONSTRAINT fk_note_completed_by FOREIGN KEY (completed_by_user_id_note) REFERENCES sec_user(id_user),
  CONSTRAINT fk_note_archived_by FOREIGN KEY (archived_by_user_id_note) REFERENCES sec_user(id_user),
  CONSTRAINT ck_note_values CHECK (priority_note IN ('low','normal','high') AND visibility_note IN ('private','shared') AND status_note IN ('open','completed','archived') AND version_note>0 AND JSON_TYPE(content_note)='OBJECT'),
  CONSTRAINT ck_note_author_actions CHECK (updated_by_user_id_note=author_user_id_note AND (completed_by_user_id_note IS NULL OR completed_by_user_id_note=author_user_id_note) AND (archived_by_user_id_note IS NULL OR archived_by_user_id_note=author_user_id_note)),
  CONSTRAINT ck_note_completion_pair CHECK ((completed_at_note IS NULL)=(completed_by_user_id_note IS NULL)),
  CONSTRAINT ck_note_archive_pair CHECK ((archived_at_note IS NULL)=(archived_by_user_id_note IS NULL)),
  CONSTRAINT ck_note_lifecycle CHECK ((status_note='open' AND completed_at_note IS NULL AND archived_at_note IS NULL) OR (status_note='completed' AND completed_at_note IS NOT NULL AND archived_at_note IS NULL) OR (status_note='archived' AND archived_at_note IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Notas principales del CRM independientes de proveedores y del layout personal';

CREATE TABLE IF NOT EXISTS crm_note_reply (
  id_note_reply BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna de una respuesta',
  public_id_note_reply CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico de la respuesta',
  note_id_note_reply BIGINT UNSIGNED NOT NULL COMMENT 'Nota a la que pertenece permanentemente la respuesta',
  author_user_id_note_reply BIGINT UNSIGNED NOT NULL COMMENT 'Autor inmutable de esta respuesta, no necesariamente autor de la nota',
  quoted_reply_id_note_reply BIGINT UNSIGNED NULL COMMENT 'Respuesta citada del mismo hilo; no crea otro contenido',
  content_note_reply JSON NOT NULL COMMENT 'Cuerpo estructurado de la respuesta validado por API',
  plain_text_note_reply TEXT NOT NULL COMMENT 'Texto de la respuesta derivado para consultas autorizadas',
  version_note_reply INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Version optimista de esta respuesta',
  withdrawn_at_note_reply DATETIME(3) NULL COMMENT 'Retiro logico de la respuesta por su autor; conserva atribucion',
  created_at_note_reply DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Publicacion UTC de la respuesta',
  updated_at_note_reply DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima edicion UTC de esta respuesta',
  PRIMARY KEY (id_note_reply),
  UNIQUE KEY uq_note_reply_public (public_id_note_reply),
  UNIQUE KEY uq_note_reply_parent (id_note_reply,note_id_note_reply),
  KEY ix_note_reply_thread (note_id_note_reply,created_at_note_reply,id_note_reply),
  CONSTRAINT fk_note_reply_note FOREIGN KEY (note_id_note_reply) REFERENCES crm_note(id_note),
  CONSTRAINT fk_note_reply_author FOREIGN KEY (author_user_id_note_reply) REFERENCES sec_user(id_user),
  CONSTRAINT fk_note_reply_quote FOREIGN KEY (quoted_reply_id_note_reply,note_id_note_reply) REFERENCES crm_note_reply(id_note_reply,note_id_note_reply),
  CONSTRAINT ck_note_reply_content CHECK (version_note_reply>0 AND JSON_TYPE(content_note_reply)='OBJECT')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Conversaciones de notas con autoria propia e hilo consistente';

CREATE TABLE IF NOT EXISTS crm_note_participant (
  id_note_participant BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del acceso individual a una nota',
  note_id_note_participant BIGINT UNSIGNED NOT NULL COMMENT 'Nota compartida por su autor',
  user_id_note_participant BIGINT UNSIGNED NOT NULL COMMENT 'Usuario interno destinatario, nunca una lista CSV',
  access_note_participant VARCHAR(16) NOT NULL DEFAULT 'reply' COMMENT 'Capacidad read o reply; nunca edicion de la nota original',
  status_note_participant VARCHAR(16) NOT NULL DEFAULT 'active' COMMENT 'Estado active o revoked del acceso explicito',
  granted_by_user_id_note_participant BIGINT UNSIGNED NOT NULL COMMENT 'Actor autorizado que concedio el acceso; la API exige autor de nota',
  revoked_by_user_id_note_participant BIGINT UNSIGNED NULL COMMENT 'Actor autorizado que retiro el acceso',
  revoked_at_note_participant DATETIME(3) NULL COMMENT 'Revocacion UTC que invalida lectura y avisos pendientes',
  following_note_participant TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Preferencia individual de seguimiento del hilo',
  muted_until_note_participant DATETIME(3) NULL COMMENT 'Silencio individual UTC sin revocar el acceso',
  created_at_note_participant DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Primer otorgamiento UTC; reactivaciones se auditan',
  updated_at_note_participant DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultimo cambio UTC de acceso o preferencias',
  PRIMARY KEY (id_note_participant),
  UNIQUE KEY uq_note_participant_user (note_id_note_participant,user_id_note_participant),
  KEY ix_note_participant_inbox (user_id_note_participant,status_note_participant,updated_at_note_participant),
  CONSTRAINT fk_note_participant_note FOREIGN KEY (note_id_note_participant) REFERENCES crm_note(id_note),
  CONSTRAINT fk_note_participant_user FOREIGN KEY (user_id_note_participant) REFERENCES sec_user(id_user),
  CONSTRAINT fk_note_participant_grant FOREIGN KEY (granted_by_user_id_note_participant) REFERENCES sec_user(id_user),
  CONSTRAINT fk_note_participant_revoke FOREIGN KEY (revoked_by_user_id_note_participant) REFERENCES sec_user(id_user),
  CONSTRAINT ck_note_participant_values CHECK (access_note_participant IN ('read','reply') AND status_note_participant IN ('active','revoked') AND following_note_participant IN (0,1)),
  CONSTRAINT ck_note_participant_revocation CHECK ((status_note_participant='active' AND revoked_at_note_participant IS NULL AND revoked_by_user_id_note_participant IS NULL) OR (status_note_participant='revoked' AND revoked_at_note_participant IS NOT NULL AND revoked_by_user_id_note_participant IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Accesos y seguimiento por persona separados de menciones y autoria';

CREATE TABLE IF NOT EXISTS crm_note_mention (
  id_note_mention BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna de una mencion estructurada',
  note_id_note_mention BIGINT UNSIGNED NOT NULL COMMENT 'Nota cuyo contenido o respuesta menciona a la persona',
  reply_id_note_mention BIGINT UNSIGNED NULL COMMENT 'Respuesta del mismo hilo; null identifica el cuerpo de la nota',
  reply_key_note_mention BIGINT UNSIGNED GENERATED ALWAYS AS (IFNULL(reply_id_note_mention,0)) STORED COMMENT 'Clave tecnica de unicidad; cero solo representa el cuerpo, no una FK ficticia',
  user_id_note_mention BIGINT UNSIGNED NOT NULL COMMENT 'Usuario mencionado por identidad nativa y no texto libre',
  content_version_note_mention INT UNSIGNED NOT NULL COMMENT 'Version de nota o respuesta que origino la mencion',
  created_at_note_mention DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Registro UTC de esta mencion; no acredita entrega ni concede acceso',
  updated_at_note_mention DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion UTC de metadata de mencion',
  PRIMARY KEY (id_note_mention),
  UNIQUE KEY uq_note_mention_message (note_id_note_mention,reply_key_note_mention,user_id_note_mention,content_version_note_mention),
  KEY ix_note_mention_user (user_id_note_mention,created_at_note_mention),
  CONSTRAINT fk_note_mention_note FOREIGN KEY (note_id_note_mention) REFERENCES crm_note(id_note),
  CONSTRAINT fk_note_mention_reply FOREIGN KEY (reply_id_note_mention,note_id_note_mention) REFERENCES crm_note_reply(id_note_reply,note_id_note_reply),
  CONSTRAINT fk_note_mention_user FOREIGN KEY (user_id_note_mention) REFERENCES sec_user(id_user),
  CONSTRAINT ck_note_mention_version CHECK (content_version_note_mention>0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Menciones multiples sin sustituir ACL ni notificaciones individuales';

CREATE TABLE IF NOT EXISTS crm_note_link (
  id_note_link BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del contexto relacionado',
  note_id_note_link BIGINT UNSIGNED NOT NULL COMMENT 'Nota relacionada sin duplicar su contenido',
  target_key_note_link CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Huella canonica de tipo fuente e identidad para evitar enlaces duplicados',
  target_kind_note_link VARCHAR(16) NOT NULL COMMENT 'Contexto view, native o external; cada tipo exige sus referencias',
  entity_type_note_link VARCHAR(40) NOT NULL COMMENT 'Tipo canonico resuelto por adaptadores registrados; no nombre SQL arbitrario',
  view_code_note_link VARCHAR(120) NULL COMMENT 'Vista registrada como marketing.home; no requiere un lead ficticio',
  lead_id_note_link BIGINT UNSIGNED NULL COMMENT 'Lead nativo relacionado cuando el tipo es lead',
  contact_id_note_link BIGINT UNSIGNED NULL COMMENT 'Contacto nativo relacionado cuando el tipo es contact',
  sales_order_id_note_link BIGINT UNSIGNED NULL COMMENT 'Orden nativa relacionada cuando el tipo es sales_order',
  calendar_event_id_note_link BIGINT UNSIGNED NULL COMMENT 'Evento nativo relacionado cuando el tipo es calendar_event',
  external_system_id_note_link BIGINT UNSIGNED NULL COMMENT 'Sistema de la entidad externa; un numero solo no identifica al proveedor',
  external_id_note_link VARCHAR(191) COLLATE utf8mb4_bin NULL COMMENT 'Identidad externa conservada como texto sin convertirla en PK nativa',
  is_primary_note_link TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Marca el destino preferido al abrir la nota',
  primary_key_note_link TINYINT GENERATED ALWAYS AS (IF(is_primary_note_link=1,1,NULL)) STORED COMMENT 'Permite un solo destino principal por nota',
  created_at_note_link DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Fecha UTC de vinculacion del contexto',
  updated_at_note_link DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion UTC del enlace',
  PRIMARY KEY (id_note_link),
  UNIQUE KEY uq_note_link_target (note_id_note_link,target_key_note_link),
  UNIQUE KEY uq_note_link_primary (note_id_note_link,primary_key_note_link),
  KEY ix_note_link_lead (lead_id_note_link,note_id_note_link),
  KEY ix_note_link_contact (contact_id_note_link,note_id_note_link),
  KEY ix_note_link_order (sales_order_id_note_link,note_id_note_link),
  KEY ix_note_link_event (calendar_event_id_note_link,note_id_note_link),
  KEY ix_note_link_external (external_system_id_note_link,entity_type_note_link,external_id_note_link),
  KEY ix_note_link_view (view_code_note_link,note_id_note_link),
  CONSTRAINT fk_note_link_note FOREIGN KEY (note_id_note_link) REFERENCES crm_note(id_note),
  CONSTRAINT fk_note_link_lead FOREIGN KEY (lead_id_note_link) REFERENCES crm_lead(id_lead),
  CONSTRAINT fk_note_link_contact FOREIGN KEY (contact_id_note_link) REFERENCES crm_contact(id_contact),
  CONSTRAINT fk_note_link_order FOREIGN KEY (sales_order_id_note_link) REFERENCES crm_sales_order(id_sales_order),
  CONSTRAINT fk_note_link_event FOREIGN KEY (calendar_event_id_note_link) REFERENCES crm_calendar_event(id_calendar_event),
  CONSTRAINT fk_note_link_system FOREIGN KEY (external_system_id_note_link) REFERENCES int_external_system(id_external_system),
  CONSTRAINT ck_note_link_primary CHECK (is_primary_note_link IN (0,1)),
  CONSTRAINT ck_note_link_target CHECK (
    (target_kind_note_link='view' AND entity_type_note_link='view' AND view_code_note_link IS NOT NULL AND CHAR_LENGTH(TRIM(view_code_note_link))>0 AND lead_id_note_link IS NULL AND contact_id_note_link IS NULL AND sales_order_id_note_link IS NULL AND calendar_event_id_note_link IS NULL AND external_system_id_note_link IS NULL AND external_id_note_link IS NULL)
    OR (target_kind_note_link='native' AND view_code_note_link IS NULL AND external_system_id_note_link IS NULL AND external_id_note_link IS NULL AND ((lead_id_note_link IS NOT NULL)+(contact_id_note_link IS NOT NULL)+(sales_order_id_note_link IS NOT NULL)+(calendar_event_id_note_link IS NOT NULL))=1 AND ((entity_type_note_link='lead' AND lead_id_note_link IS NOT NULL) OR (entity_type_note_link='contact' AND contact_id_note_link IS NOT NULL) OR (entity_type_note_link='sales_order' AND sales_order_id_note_link IS NOT NULL) OR (entity_type_note_link='calendar_event' AND calendar_event_id_note_link IS NOT NULL)))
    OR (target_kind_note_link='external' AND entity_type_note_link IN ('lead','contact','sales_order','calendar_event') AND view_code_note_link IS NULL AND lead_id_note_link IS NULL AND contact_id_note_link IS NULL AND sales_order_id_note_link IS NULL AND calendar_event_id_note_link IS NULL AND external_system_id_note_link IS NOT NULL AND external_id_note_link IS NOT NULL AND CHAR_LENGTH(TRIM(external_id_note_link))>0)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Contextos de vista y relaciones nativas o externas con validacion de identidad';

CREATE TABLE IF NOT EXISTS crm_note_placement (
  id_note_placement BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del layout individual',
  note_id_note_placement BIGINT UNSIGNED NOT NULL COMMENT 'Nota cuya presentacion administra esta persona',
  user_id_note_placement BIGINT UNSIGNED NOT NULL COMMENT 'Usuario propietario de la posicion; no cambia autor ni contenido',
  context_code_note_placement VARCHAR(120) NOT NULL COMMENT 'Vista o contexto registrado; la API vuelve a autorizar su lectura',
  viewport_class_note_placement VARCHAR(16) NOT NULL DEFAULT 'desktop' COMMENT 'Clase desktop, tablet o mobile para restauracion adaptable',
  anchor_mode_note_placement VARCHAR(16) NOT NULL DEFAULT 'context' COMMENT 'Context desplaza con vista; viewport permanece fijo al hacer scroll',
  x_note_placement DECIMAL(12,4) NOT NULL DEFAULT 0 COMMENT 'Posicion horizontal CSS no negativa respecto al espacio de anclaje',
  y_note_placement DECIMAL(12,4) NOT NULL DEFAULT 0 COMMENT 'Posicion vertical CSS no negativa respecto al espacio de anclaje',
  width_note_placement INT UNSIGNED NOT NULL DEFAULT 280 COMMENT 'Ancho CSS de la nota limitado para restaurar dentro de pantalla',
  height_note_placement INT UNSIGNED NOT NULL DEFAULT 200 COMMENT 'Alto CSS de la nota limitado para restaurar dentro de pantalla',
  collapsed_note_placement TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Minimizacion personal sin completar la nota',
  hidden_at_note_placement DATETIME(3) NULL COMMENT 'Ocultamiento individual UTC sin modificar a otros participantes',
  layout_version_note_placement INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Version optimista del layout independiente del texto',
  created_at_note_placement DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Primer guardado UTC de esta presentacion personal',
  updated_at_note_placement DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultimo guardado UTC; no actualiza fecha de contenido',
  PRIMARY KEY (id_note_placement),
  UNIQUE KEY uq_note_placement_user_context (note_id_note_placement,user_id_note_placement,context_code_note_placement,viewport_class_note_placement),
  KEY ix_note_placement_user_view (user_id_note_placement,context_code_note_placement),
  CONSTRAINT fk_note_placement_note FOREIGN KEY (note_id_note_placement) REFERENCES crm_note(id_note),
  CONSTRAINT fk_note_placement_user FOREIGN KEY (user_id_note_placement) REFERENCES sec_user(id_user),
  CONSTRAINT ck_note_placement_values CHECK (viewport_class_note_placement IN ('desktop','tablet','mobile') AND anchor_mode_note_placement IN ('context','viewport') AND x_note_placement>=0 AND y_note_placement>=0 AND width_note_placement BETWEEN 160 AND 1600 AND height_note_placement BETWEEN 80 AND 1600 AND collapsed_note_placement IN (0,1) AND layout_version_note_placement>0 AND CHAR_LENGTH(TRIM(context_code_note_placement))>0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Posicion tamano PIN y ocultamiento por usuario, nunca un movimiento compartido';

CREATE TABLE IF NOT EXISTS int_note_external_reference (
  id_note_external_reference BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del vinculo de compatibilidad',
  note_id_note_external_reference BIGINT UNSIGNED NOT NULL COMMENT 'Nota principal nativa cuya copia depende de un adaptador',
  external_system_id_note_external_reference BIGINT UNSIGNED NOT NULL COMMENT 'Sistema registrado que contiene la copia; no campo especifico de proveedor',
  external_id_note_external_reference VARCHAR(191) COLLATE utf8mb4_bin NULL COMMENT 'Identidad de la copia; null hasta confirmar la primera sincronizacion',
  sync_status_note_external_reference VARCHAR(16) NOT NULL DEFAULT 'pending' COMMENT 'Estado pending, synced, failed o disabled de la proyeccion',
  requested_version_note_external_reference INT UNSIGNED NOT NULL COMMENT 'Version nativa que debe representar la copia',
  synced_version_note_external_reference INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Ultima version confirmada; cero significa que no existe confirmacion',
  last_synced_at_note_external_reference DATETIME(3) NULL COMMENT 'Confirmacion UTC de la ultima version aplicada externamente',
  last_error_code_note_external_reference VARCHAR(80) NULL COMMENT 'Codigo tecnico acotado sin cuerpos privados ni secretos',
  created_at_note_external_reference DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion UTC del vinculo; no ejecuta escrituras externas',
  updated_at_note_external_reference DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultimo cambio UTC del estado de sincronizacion',
  PRIMARY KEY (id_note_external_reference),
  UNIQUE KEY uq_note_external_system (note_id_note_external_reference,external_system_id_note_external_reference),
  UNIQUE KEY uq_note_external_identity (external_system_id_note_external_reference,external_id_note_external_reference),
  KEY ix_note_external_pending (sync_status_note_external_reference,updated_at_note_external_reference),
  CONSTRAINT fk_note_external_note FOREIGN KEY (note_id_note_external_reference) REFERENCES crm_note(id_note),
  CONSTRAINT fk_note_external_system FOREIGN KEY (external_system_id_note_external_reference) REFERENCES int_external_system(id_external_system),
  CONSTRAINT ck_note_external_status CHECK (sync_status_note_external_reference IN ('pending','synced','failed','disabled') AND requested_version_note_external_reference>0 AND synced_version_note_external_reference<=requested_version_note_external_reference),
  CONSTRAINT ck_note_external_confirmed CHECK ((synced_version_note_external_reference=0 AND last_synced_at_note_external_reference IS NULL) OR (synced_version_note_external_reference>0 AND external_id_note_external_reference IS NOT NULL AND last_synced_at_note_external_reference IS NOT NULL)),
  CONSTRAINT ck_note_external_synced CHECK (sync_status_note_external_reference<>'synced' OR (external_id_note_external_reference IS NOT NULL AND synced_version_note_external_reference=requested_version_note_external_reference AND last_synced_at_note_external_reference IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Copias externas versionadas de notas con autoridad nativa y sin importar historia';
